final class Registry {
    private Registry() { }
    private static class Holder { static final Registry INSTANCE = new Registry(); }
    static Registry get() { return Holder.INSTANCE; }          // lazy, thread-safe, no locks
}
final class Lazy {
    private static volatile Lazy instance;                      // volatile is essential
    static Lazy get() {
        Lazy r = instance;
        if (r == null) {
            synchronized (Lazy.class) {
                r = instance;
                if (r == null) instance = r = new Lazy();
            }
        }
        return r;
    }
}

