sealed interface Shape permits Circle, Rect, Tri {}
record Circle(double r) implements Shape {}
record Rect(double w, double h) implements Shape {}
record Tri(double b, double h) implements Shape {}

static double area(Shape s) {
    return switch (s) {
        case Circle c -> Math.PI * c.r() * c.r();
        case Rect(double w, double h) -> w * h;
        case Tri t when t.b() <= 0 -> 0;
        case Tri(double b, double h) -> 0.5 * b * h;
    };
}
// area(new Circle(1)) = 3.14, area(new Rect(2,3)) = 6.0, area(new Tri(4,5)) = 10.0

static String describe(Object o) {
    return switch (o) {
        case null -> "null!";
        case Integer i when i > 10 -> "big int " + i;
        case Integer i -> "int " + i;
        case String s -> "string of " + s.length();
        case int[] a -> "int array " + a.length;
        default -> "other " + o.getClass().getSimpleName();
    };
}
