    static boolean f(String s) { calls++; System.out.print(s + " "); return false; }
    public static void main(String[] args) {
        boolean r1 = f("a") && t("b") || t("c");
        System.out.println("-> " + r1);
        boolean r2 = t("d") | f("e") & t("f");
        System.out.println("-> " + r2);
        boolean r3 = f("g") & t("h");
        System.out.println("-> " + r3 + " calls=" + calls);
        int x = 5;
        boolean r4 = x > 3 || x++ > 0;
        System.out.println(x);
        System.out.println(true ^ true);
    }
}

