static String reverseWords(String s) {
    String[] parts = s.trim().split("\\s+");
    StringBuilder sb = new StringBuilder();
    for (int i = parts.length - 1; i >= 0; i--) {
        sb.append(parts[i]);
        if (i > 0) sb.append(' ');
    }
    return sb.toString();
}

static String reverse(String s) {            // reverse characters, in place on a char[]
    char[] c = s.toCharArray();
    for (int i = 0, j = c.length - 1; i < j; i++, j--) {
        char t = c[i]; c[i] = c[j]; c[j] = t;
    }
    return new String(c);
}

static boolean isPalindrome(String s) {
    int i = 0, j = s.length() - 1;
    while (i < j) {
        while (i < j && !Character.isLetterOrDigit(s.charAt(i))) i++;
        while (i < j && !Character.isLetterOrDigit(s.charAt(j))) j--;
        if (Character.toLowerCase(s.charAt(i++)) != Character.toLowerCase(s.charAt(j--)))
            return false;
    }
    return true;
}

static boolean isAnagram(String a, String b) {
    if (a.length() != b.length()) return false;
    int[] count = new int[26];
    for (int i = 0; i < a.length(); i++) {
        count[a.charAt(i) - 'a']++;
        count[b.charAt(i) - 'a']--;
    }
    for (int n : count) if (n != 0) return false;
    return true;
}

static int firstUniqueChar(String s) {
    int[] freq = new int[128];
    for (char c : s.toCharArray()) freq[c]++;
    for (int i = 0; i < s.length(); i++)
        if (freq[s.charAt(i)] == 1) return i;
    return -1;
}

static int longestUniqueBrute(String s) {            // O(n^2) time, O(min(n, 128)) space
    int best = 0;
    for (int i = 0; i < s.length(); i++) {
        Set<Character> seen = new HashSet<>();
        for (int j = i; j < s.length() && seen.add(s.charAt(j)); j++)
            best = Math.max(best, j - i + 1);
    }
    return best;
}

static int longestUnique(String s) {                 // O(n) time: sliding window
    int[] lastSeen = new int[128];
    Arrays.fill(lastSeen, -1);
    int best = 0, start = 0;
    for (int end = 0; end < s.length(); end++) {
        char c = s.charAt(end);
        if (lastSeen[c] >= start) start = lastSeen[c] + 1;   // jump past the duplicate
        lastSeen[c] = end;
        best = Math.max(best, end - start + 1);
    }
    return best;
}

static String compress(String s) {
    if (s.isEmpty()) return s;
    StringBuilder sb = new StringBuilder();
    int run = 1;
    for (int i = 1; i <= s.length(); i++) {
        if (i < s.length() && s.charAt(i) == s.charAt(i - 1)) {
            run++;
        } else {
            sb.append(s.charAt(i - 1)).append(run);
            run = 1;
        }
    }
    return sb.length() < s.length() ? sb.toString() : s;
}

static String longestCommonPrefix(String[] words) {
    if (words.length == 0) return "";
    String prefix = words[0];
    for (String w : words) {
        while (!w.startsWith(prefix)) prefix = prefix.substring(0, prefix.length() - 1);
    }
    return prefix;
}

static String longestPalindrome(String s) {          // expand around centre: O(n^2), O(1) space
    int lo = 0, hi = 0;
    for (int centre = 0; centre < s.length(); centre++) {
        for (int odd = 0; odd < 2; odd++) {          // odd: centre is a char; even: between two
            int l = centre, r = centre + odd;
            while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) { l--; r++; }
            if (r - l - 1 > hi - lo) { lo = l + 1; hi = r; }
        }
    }
    return s.substring(lo, hi);
}

static void moveZeroes(int[] a) {
    int write = 0;
    for (int read = 0; read < a.length; read++)
        if (a[read] != 0) {
            int t = a[write]; a[write] = a[read]; a[read] = t;
            write++;
        }
}

static void rotate(int[] a, int k) {                 // rotate right by k, O(n) time, O(1) space
    k %= a.length;
    reverse(a, 0, a.length - 1);
    reverse(a, 0, k - 1);
    reverse(a, k, a.length - 1);
}
static void reverse(int[] a, int i, int j) {
    while (i < j) { int t = a[i]; a[i++] = a[j]; a[j--] = t; }
}

static int maxSubarrayBrute(int[] a) {               // O(n^2)
    int best = Integer.MIN_VALUE;
    for (int i = 0; i < a.length; i++) {
        int sum = 0;
        for (int j = i; j < a.length; j++) {
            sum += a[j];
            best = Math.max(best, sum);
        }
    }
    return best;
}

static int maxSubarray(int[] a) {                    // Kadane: O(n) time, O(1) space
    int best = a[0], endingHere = a[0];
    for (int i = 1; i < a.length; i++) {
        endingHere = Math.max(a[i], endingHere + a[i]);   // extend, or start fresh here
        best = Math.max(best, endingHere);
    }
    return best;
}

static int maxProfit(int[] prices) {                 // one buy, one later sell
    int minSoFar = Integer.MAX_VALUE, best = 0;
    for (int p : prices) {
        minSoFar = Math.min(minSoFar, p);
        best = Math.max(best, p - minSoFar);
    }
    return best;
}

static int missingNumber(int[] a) {                  // a holds 0..n except one value
    int xor = a.length;
    for (int i = 0; i < a.length; i++) xor ^= i ^ a[i];
    return xor;
}

static int[] productExceptSelf(int[] a) {            // no division, O(n) time
    int n = a.length;
    int[] out = new int[n];
    out[0] = 1;
    for (int i = 1; i < n; i++) out[i] = out[i - 1] * a[i - 1];   // product of everything left
    int right = 1;
    for (int i = n - 1; i >= 0; i--) {
        out[i] *= right;                                          // times everything right
        right *= a[i];
    }
    return out;
}

static int binarySearch(int[] sorted, int target) {
    int lo = 0, hi = sorted.length - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;               // (lo + hi) / 2 can overflow int
        if (sorted[mid] == target) return mid;
        if (sorted[mid] < target) lo = mid + 1; else hi = mid - 1;
    }
    return -(lo + 1);                               // same convention as Arrays.binarySearch
}

static int majority(int[] a) {                       // Boyer-Moore voting, O(n) time, O(1) space
    int candidate = 0, votes = 0;
    for (int x : a) {
        if (votes == 0) candidate = x;
        votes += (x == candidate) ? 1 : -1;
    }
    return candidate;                                // valid only if a majority is guaranteed
}

