static int[] twoSum(int[] nums, int target) {         // O(n) time, O(n) space
    Map<Integer, Integer> indexOf = new HashMap<>();   // value -> index where seen
    for (int i = 0; i < nums.length; i++) {
        Integer j = indexOf.get(target - nums[i]);
        if (j != null) return new int[]{j, i};
        indexOf.put(nums[i], i);
    }
    return new int[0];
}

static boolean hasDuplicate(int[] nums) {
    Set<Integer> seen = new HashSet<>();
    for (int n : nums) if (!seen.add(n)) return true;   // add returns false if already present
    return false;
}

static Collection<List<String>> groupAnagrams(String[] words) {
    Map<String, List<String>> groups = new LinkedHashMap<>();
    for (String w : words) {
        char[] c = w.toCharArray();
        Arrays.sort(c);
        groups.computeIfAbsent(new String(c), k -> new ArrayList<>()).add(w);
    }
    return groups.values();
}

static List<String> topK(String[] words, int k) {      // O(n log k)
    Map<String, Integer> freq = new HashMap<>();
    for (String w : words) freq.merge(w, 1, Integer::sum);
    // min-heap of size k: the weakest of the current top k sits at the head
    PriorityQueue<Map.Entry<String, Integer>> heap = new PriorityQueue<>(
        Map.Entry.<String, Integer>comparingByValue()
            .thenComparing(Map.Entry.<String, Integer>comparingByKey().reversed()));
    for (Map.Entry<String, Integer> e : freq.entrySet()) {
        heap.offer(e);
        if (heap.size() > k) heap.poll();
    }
    List<String> out = new ArrayList<>();
    while (!heap.isEmpty()) out.add(heap.poll().getKey());
    Collections.reverse(out);                          // strongest first
    return out;
}

static boolean balanced(String s) {
    Deque<Character> stack = new ArrayDeque<>();
    for (char c : s.toCharArray()) {
        switch (c) {
            case '(' -> stack.push(')');
            case '[' -> stack.push(']');
            case '{' -> stack.push('}');
            case ')', ']', '}' -> {
                if (stack.isEmpty() || stack.pop() != c) return false;
            }
            default -> { }                              // ignore other characters
        }
    }
    return stack.isEmpty();
}

static int[][] mergeIntervals(int[][] in) {
    int[][] sorted = in.clone();
    Arrays.sort(sorted, Comparator.comparingInt(iv -> iv[0]));
    List<int[]> out = new ArrayList<>();
    for (int[] iv : sorted) {
        if (out.isEmpty() || out.get(out.size() - 1)[1] < iv[0]) {
            out.add(new int[]{iv[0], iv[1]});           // gap: start a new interval
        } else {
            int[] last = out.get(out.size() - 1);
            last[1] = Math.max(last[1], iv[1]);         // overlap: extend the last one
        }
    }
    return out.toArray(new int[0][]);
}

static class LruCache<K, V> extends LinkedHashMap<K, V> {
    private final int capacity;
    LruCache(int capacity) {
        super(16, 0.75f, true);                        // true = access order
        this.capacity = capacity;
    }
    @Override
    protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
        return size() > capacity;                      // called after every put
    }
}

static class ManualLru {
    private static class Node {
        int key, value; Node prev, next;
        Node(int k, int v) { key = k; value = v; }
    }
    private final int capacity;
    private final Map<Integer, Node> map = new HashMap<>();
    private final Node head = new Node(0, 0), tail = new Node(0, 0);   // sentinels
    ManualLru(int capacity) { this.capacity = capacity; head.next = tail; tail.prev = head; }

    int get(int key) {
        Node n = map.get(key);
        if (n == null) return -1;
        unlink(n); addFirst(n);                        // most recently used goes to the front
        return n.value;
    }
    void put(int key, int value) {
        Node n = map.get(key);
        if (n != null) { n.value = value; unlink(n); addFirst(n); return; }
        if (map.size() == capacity) {                  // evict the node before the tail
            Node lru = tail.prev;
            unlink(lru); map.remove(lru.key);
        }
        n = new Node(key, value);
        map.put(key, n); addFirst(n);
    }
    private void unlink(Node n) { n.prev.next = n.next; n.next.prev = n.prev; }
    private void addFirst(Node n) {
        n.next = head.next; n.prev = head;
        head.next.prev = n; head.next = n;
    }
}

static List<List<Integer>> permutations(int[] nums) {
    List<List<Integer>> out = new ArrayList<>();
    backtrack(nums, new boolean[nums.length], new ArrayList<>(), out);
    return out;
}
private static void backtrack(int[] nums, boolean[] used, List<Integer> cur,
                              List<List<Integer>> out) {
    if (cur.size() == nums.length) { out.add(new ArrayList<>(cur)); return; }   // copy!
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true; cur.add(nums[i]);              // choose
        backtrack(nums, used, cur, out);               // explore
        cur.remove(cur.size() - 1); used[i] = false;   // un-choose
    }
}

static List<List<Integer>> subsets(int[] nums) {
    List<List<Integer>> out = new ArrayList<>();
    out.add(new ArrayList<>());
    for (int x : nums) {
        int size = out.size();
        for (int i = 0; i < size; i++) {               // every existing subset, plus x
            List<Integer> copy = new ArrayList<>(out.get(i));
            copy.add(x);
            out.add(copy);
        }
    }
    return out;
}

static int countIslands(char[][] grid) {
    int count = 0;
    for (int r = 0; r < grid.length; r++)
        for (int c = 0; c < grid[0].length; c++)
            if (grid[r][c] == '1') { count++; sink(grid, r, c); }
    return count;
}
private static void sink(char[][] g, int r, int c) {   // DFS: flood the whole island
    if (r < 0 || c < 0 || r >= g.length || c >= g[0].length || g[r][c] != '1') return;
    g[r][c] = '0';
    sink(g, r + 1, c); sink(g, r - 1, c); sink(g, r, c + 1); sink(g, r, c - 1);
}

static int shortestPath(char[][] maze) {               // 'S' start, 'E' end, '#' wall
    int rows = maze.length, cols = maze[0].length;
    int[][] dist = new int[rows][cols];
    for (int[] row : dist) Arrays.fill(row, -1);
    Deque<int[]> queue = new ArrayDeque<>();
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < cols; c++)
            if (maze[r][c] == 'S') { queue.add(new int[]{r, c}); dist[r][c] = 0; }
    int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    while (!queue.isEmpty()) {
        int[] cur = queue.poll();
        if (maze[cur[0]][cur[1]] == 'E') return dist[cur[0]][cur[1]];
        for (int[] d : dirs) {
            int nr = cur[0] + d[0], nc = cur[1] + d[1];
            if (nr >= 0 && nc >= 0 && nr < rows && nc < cols
                    && maze[nr][nc] != '#' && dist[nr][nc] == -1) {
                dist[nr][nc] = dist[cur[0]][cur[1]] + 1;
                queue.add(new int[]{nr, nc});
            }
        }
    }
    return -1;
}

record TreeNode(int val, TreeNode left, TreeNode right) {}

static List<List<Integer>> levelOrder(TreeNode root) {
    List<List<Integer>> out = new ArrayList<>();
    if (root == null) return out;
    Deque<TreeNode> queue = new ArrayDeque<>();
    queue.add(root);
    while (!queue.isEmpty()) {
        int width = queue.size();                         // nodes on this level
        List<Integer> level = new ArrayList<>();
        for (int i = 0; i < width; i++) {
            TreeNode n = queue.poll();
            level.add(n.val());
            if (n.left() != null) queue.add(n.left());
            if (n.right() != null) queue.add(n.right());
        }
        out.add(level);
    }
    return out;
}

static int height(TreeNode n) {
    return n == null ? 0 : 1 + Math.max(height(n.left()), height(n.right()));
}

static long fibNaive(int n) { return n < 2 ? n : fibNaive(n - 1) + fibNaive(n - 2); }  // O(2^n)

static long fibMemo(int n, long[] memo) {                 // top-down: O(n) time, O(n) space
    if (n < 2) return n;
    if (memo[n] != 0) return memo[n];
    return memo[n] = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
}

static long fibBottomUp(int n) {                          // bottom-up: O(n) time, O(1) space
    long a = 0, b = 1;
    for (int i = 0; i < n; i++) { long t = a + b; a = b; b = t; }
    return a;
}

static int coinChange(int[] coins, int amount) {          // fewest coins, or -1
    int[] dp = new int[amount + 1];                       // dp[a] = fewest coins to make a
    Arrays.fill(dp, amount + 1);                          // "infinity"
    dp[0] = 0;
    for (int a = 1; a <= amount; a++)
        for (int coin : coins)
            if (coin <= a) dp[a] = Math.min(dp[a], dp[a - coin] + 1);
    return dp[amount] > amount ? -1 : dp[amount];
}

static int lcs(String a, String b) {                      // O(n*m) time and space
    int[][] dp = new int[a.length() + 1][b.length() + 1];
    for (int i = 1; i <= a.length(); i++)
        for (int j = 1; j <= b.length(); j++)
            dp[i][j] = a.charAt(i - 1) == b.charAt(j - 1)
                ? dp[i - 1][j - 1] + 1
                : Math.max(dp[i - 1][j], dp[i][j - 1]);
    return dp[a.length()][b.length()];
}

static int knapsack(int[] weight, int[] value, int capacity) {   // 0/1: each item once
    int[] dp = new int[capacity + 1];                     // dp[w] = best value within weight w
    for (int i = 0; i < weight.length; i++)
        for (int w = capacity; w >= weight[i]; w--)       // downwards: reuse is impossible
            dp[w] = Math.max(dp[w], dp[w - weight[i]] + value[i]);
    return dp[capacity];
}

