static class OddEven {
    private final Object lock = new Object();
    private int next = 1;                               // guarded by lock
    private final int max;
    OddEven(int max) { this.max = max; }

    void print(boolean odd, StringBuilder out) throws InterruptedException {
        synchronized (lock) {
            while (next <= max) {
                while (next <= max && (next % 2 == 1) != odd) lock.wait();   // not my turn
                if (next > max) break;
                out.append(odd ? "odd:" : "even:").append(next++).append(' ');
                lock.notifyAll();                       // wake the partner
            }
            lock.notifyAll();                           // let a waiting partner exit
        }
    }
}

static long producerConsumer() throws Exception {
    BlockingQueue<Integer> queue = new ArrayBlockingQueue<>(4);   // bounded: back-pressure
    final int POISON = -1;                              // tells the consumer to stop
    AtomicLong sum = new AtomicLong();
    Thread producer = new Thread(() -> {
        try {
            for (int i = 1; i <= 100; i++) queue.put(i);          // blocks when full
            queue.put(POISON);
        } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    });
    Thread consumer = new Thread(() -> {
        try {
            for (int v; (v = queue.take()) != POISON; ) sum.addAndGet(v);   // blocks when empty
        } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    });
    producer.start(); consumer.start();
    producer.join(); consumer.join();
    return sum.get();
}

static class Account {
    final int id; long balance;
    final Lock lock = new ReentrantLock();
    Account(int id, long balance) { this.id = id; this.balance = balance; }
}

static void transferBad(Account from, Account to, long amount) {
    from.lock.lock();                                   // thread 1: A then B
    try {                                               // thread 2: B then A  -> deadlock
        sleepQuietly(50);
        to.lock.lock();
        try { from.balance -= amount; to.balance += amount; } finally { to.lock.unlock(); }
    } finally { from.lock.unlock(); }
}

static void transferGood(Account from, Account to, long amount) {
    Account first = from.id < to.id ? from : to;        // always lock the lower id first
    Account second = first == from ? to : from;
    first.lock.lock();
    try {
        sleepQuietly(50);
        second.lock.lock();
        try { from.balance -= amount; to.balance += amount; } finally { second.lock.unlock(); }
    } finally { first.lock.unlock(); }
}

static class Counters {
    int plain;                                          // NOT thread-safe
    int synced;
    final AtomicInteger atomic = new AtomicInteger();
    final LongAdder adder = new LongAdder();
    synchronized void incSynced() { synced++; }
}

static Counters countWithThreads(int threads, int perThread) throws Exception {
    Counters c = new Counters();
    ExecutorService pool = Executors.newFixedThreadPool(threads);
    for (int t = 0; t < threads; t++) {
        pool.submit(() -> {
            for (int i = 0; i < perThread; i++) {
                c.plain++;                              // read-modify-write: updates get lost
                c.incSynced();
                c.atomic.incrementAndGet();
                c.adder.increment();
            }
        });
    }
    pool.shutdown();
    pool.awaitTermination(30, TimeUnit.SECONDS);
    return c;
}

static class Cache<K, V> {
    private final ConcurrentHashMap<K, V> map = new ConcurrentHashMap<>();
    private final java.util.function.Function<K, V> loader;
    Cache(java.util.function.Function<K, V> loader) { this.loader = loader; }

    V get(K key) {
        return map.computeIfAbsent(key, loader);        // atomic per key: loader runs once
    }
}

