static class TokenBucket {
    private final long capacity, refillPerSecond;
    private final LongSupplier nanoClock;               // injectable, so tests are deterministic
    private double tokens;                              // guarded by this
    private long lastRefill;

    TokenBucket(long capacity, long refillPerSecond, LongSupplier nanoClock) {
        this.capacity = capacity; this.refillPerSecond = refillPerSecond;
        this.nanoClock = nanoClock; this.tokens = capacity; this.lastRefill = nanoClock.getAsLong();
    }

    synchronized boolean tryAcquire() {
        long now = nanoClock.getAsLong();
        tokens = Math.min(capacity, tokens + (now - lastRefill) / 1e9 * refillPerSecond);
        lastRefill = now;
        if (tokens >= 1) { tokens -= 1; return true; }
        return false;
    }
}

static long sumWithPool(long[] data, int parts) throws Exception {
    ExecutorService pool = Executors.newFixedThreadPool(parts);
    try {
        List<Future<Long>> futures = new ArrayList<>();
        int chunk = (data.length + parts - 1) / parts;
        for (int p = 0; p < parts; p++) {
            int from = p * chunk, to = Math.min(data.length, from + chunk);
            futures.add(pool.submit(() -> {
                long s = 0;
                for (int i = from; i < to; i++) s += data[i];
                return s;
            }));
        }
        long total = 0;
        for (Future<Long> f : futures) total += f.get();
        return total;
    } finally {
        pool.shutdown();
    }
}

static class SumTask extends RecursiveTask<Long> {
    private final long[] data; private final int from, to;
    SumTask(long[] data, int from, int to) { this.data = data; this.from = from; this.to = to; }
    @Override protected Long compute() {
        if (to - from <= 10_000) {                      // small enough: do it directly
            long s = 0;
            for (int i = from; i < to; i++) s += data[i];
            return s;
        }
        int mid = (from + to) >>> 1;
        SumTask left = new SumTask(data, from, mid);
        left.fork();                                    // run the left half asynchronously
        long right = new SumTask(data, mid, to).compute();
        return left.join() + right;
    }
}

